namespace {
template <typename Controller, typename Queue>
struct ReadableState {
  Controller controller;
  kj::Own<typename Queue::Consumer> consumer;
  // The ReadableStreamJsController that owns the ValueReadable/ByteReadable holding
  // this state, so the pointer is always valid while this state exists.
  kj::Ptr<ReadableStreamJsController> owner;

  ReadableState(Controller controller,
      kj::Own<typename Queue::Consumer> consumer,
      kj::Ptr<ReadableStreamJsController> owner)
      : controller(kj::mv(controller)),
        consumer(kj::mv(consumer)),
        owner(kj::mv(owner)) {}

  ReadableState(Controller controller,
      kj::Weak<typename Queue::ConsumerImpl::StateListener> listener,
      kj::Ptr<ReadableStreamJsController> owner)
      : ReadableState(
            controller.addRef(), controller->getConsumer(kj::mv(listener)), kj::mv(owner)) {}

  ReadableState clone(jsg::Lock& js,
      kj::Weak<typename Queue::ConsumerImpl::StateListener> listener,
      kj::Ptr<ReadableStreamJsController> owner) {
    return ReadableState(controller.addRef(), consumer->clone(js, kj::mv(listener)), kj::mv(owner));
  }
};

struct ValueReadable final: public kj::PtrTarget,
                            public api::ValueQueue::ConsumerImpl::StateListener {
  using State = ReadableState<DefaultController, ValueQueue>;
  kj::Maybe<State> state;
  bool reading = false;
  bool pendingCancel = false;

  JSG_MEMORY_INFO(ValueReadable) {
    KJ_IF_SOME(s, state) {
      tracker.trackField("controller", s.controller);
      tracker.trackField("consumer", s.consumer);
    }
  }

  void visitForGc(jsg::GcVisitor& visitor) {
    KJ_IF_SOME(s, state) {
      visitor.visit(s.controller, *s.consumer);
    }
  }

  ValueReadable(DefaultController controller, kj::Ptr<ReadableStreamJsController> owner)
      : state(State(kj::mv(controller), addWeakToThis(), kj::mv(owner))) {}

  ValueReadable(jsg::Lock& js, kj::Ptr<ReadableStreamJsController> owner, ValueReadable& other)
      : state(KJ_ASSERT_NONNULL(other.state).clone(js, addWeakToThis(), kj::mv(owner))) {}

  KJ_DISALLOW_COPY_AND_MOVE(ValueReadable);

  void cancelPendingReads(jsg::Lock& js, jsg::JsValue reason) {
    KJ_IF_SOME(s, state) {
      s.consumer->cancelPendingReads(js, reason);
    }
  }

  kj::Own<ValueReadable> clone(jsg::Lock& js, kj::Ptr<ReadableStreamJsController> owner) {
    // A single ReadableStreamDefaultController can have multiple consumers.
    // When the ValueReadable constructor is used, the new consumer is added
    // and starts to receive new data that becomes enqueued. When clone
    // is used, any state currently held by this consumer is copied to the
    // new consumer.
    return kj::heap<ValueReadable>(js, kj::mv(owner), *this);
  }

  jsg::Promise<ReadResult> read(jsg::Lock& js) {
    KJ_IF_SOME(s, state) {
      auto prp = js.newPromiseAndResolver<ReadResult>();
      reading = true;
      KJ_DEFER(reading = false);
      s.consumer->read(js,
          kj::heap<ValueQueue::ReadRequest>({
            .resolver = kj::mv(prp.resolver),
          }));
      // reading is reset by KJ_DEFER above.
      if (pendingCancel) {
        // If we were canceled while reading, we need to drop our state now.
        state = kj::none;
        pendingCancel = false;
      }
      return kj::mv(prp.promise);
    }

    // We are canceled! There's nothing to do.
    return js.resolvedPromise(ReadResult{.done = true});
  }

  jsg::Promise<DrainingReadResult> drainingRead(jsg::Lock& js, size_t maxRead) {
    KJ_IF_SOME(s, state) {
      // Note: We do NOT call beginOperation()/endOperation() here. The caller
      // (ReadableStreamJsController::drainingRead) manages the operation scope
      // around both this call and the returned promise's lifetime. If we added
      // our own beginOperation/endOperation here, the endOperation would fire
      // before the caller's wrapDrainingRead could set up its .then() callbacks,
      // potentially destroying the Consumer while the returned promise still has
      // dangling this-capturing callbacks from consumer->drainingRead().
      return s.consumer->drainingRead(js, maxRead);
    }

    // We are canceled! Return done with empty chunks.
    return js.resolvedPromise(DrainingReadResult{
      .chunks = kj::Array<kj::Array<kj::byte>>(),
      .done = true,
    });
  }

  jsg::Promise<void> cancel(jsg::Lock& js, jsg::Optional<jsg::JsValue> maybeReason) {
    // When a ReadableStream is canceled, the expected behavior is that the underlying
    // controller is notified and the cancel algorithm on the underlying source is
    // called. When there are multiple ReadableStreams sharing consumption of a
    // controller, however, it should act as a shared pointer of sorts, canceling
    // the underlying controller only when the last reader is canceled.
    // Here, we rely on the controller implementing the correct behavior since it owns
    // the queue that knows about all of the attached consumers.
    if (pendingCancel) return js.resolvedPromise();
    KJ_IF_SOME(s, state) {
      // Check if there's a pending draining read before calling cancel, since cancel
      // will resolve the pending read and we need to know if we should defer destruction.
      bool hasPendingDrainingRead = s.consumer->hasPendingDrainingRead();
      s.consumer->cancel(js, maybeReason);
      auto promise = s.controller->cancel(js, maybeReason);
      // If we're currently in a read (sync or draining), we need to wait for that to
      // finish before dropping our state. For draining reads, the promise callbacks
      // capture 'this' (the Consumer) to clear hasPendingDrainingRead. If we destroy
      // the state now, those callbacks will UAF.
      if (reading || hasPendingDrainingRead) {
        pendingCancel = true;
      } else {
        state = kj::none;
      }
      return kj::mv(promise);
    }

    return js.resolvedPromise();
  }

  void onConsumerClose(jsg::Lock& js) override {
    // Called by the consumer when a state change to closed happens.
    // We need to notify the owner. Note that the owner may drop this
    // readable in doClose so it is not safe to access anything on this
    // after calling doClose.
    KJ_IF_SOME(s, state) {
      s.owner->doClose(js);
    }
  }

  void onConsumerError(jsg::Lock& js, jsg::JsValue reason) override {
    // Called by the consumer when a state change to errored happens.
    // We need to notify the owner. Note that the owner may drop this
    // readable in doClose so it is not safe to access anything on this
    // after calling doError.
    KJ_IF_SOME(s, state) {
      s.owner->doError(js, reason);
    }
  }

  bool onConsumerWantsData(jsg::Lock& js) override {
    // Called by the consumer when it has a queued pending read and needs
    // data to be provided to fulfill it. We need to notify the controller
    // to initiate pulling to provide the data.
    // Returns true if the pull completed synchronously (meaning more pumping
    // might yield additional synchronous data), false otherwise.
    KJ_IF_SOME(s, state) {
      // Save a COPY of the owner Ptr before calling pull — not a reference to the
      // member, which dies with `this`. The pull callback may trigger close/error
      // which could destroy this ValueReadable. By using beginOperation(), we ensure
      // doClose/doError defers the actual destruction until after we return. The
      // owner itself outlives us: only the owner can drop this ValueReadable.
      auto owner = s.owner;
      owner->state.beginOperation();

      // For draining reads, use forcePull to bypass backpressure checks.
      // This ensures we pull all available data regardless of highWaterMark.
      if (s.consumer->hasPendingDrainingRead()) {
        s.controller->forcePull(js);
      } else {
        s.controller->pull(js);
      }

      // Check if state is still valid BEFORE calling endOperation(),
      // because that call may destroy this ValueReadable if close was deferred.
      bool result =
          state.map([](State& s2) { return !s2.controller->isPulling(); }).orDefault(false);

      // Process any deferred close/error. This may destroy this ValueReadable.
      if (owner->state.endOperation()) {
        // A pending state was applied. Call the appropriate callback.
        if (owner->state.template is<StreamStates::Closed>()) {
          owner->lock.onClose(js);
        } else if (owner->state.template is<StreamStates::Errored>()) {
          KJ_IF_SOME(err, owner->state.template tryGetUnsafe<StreamStates::Errored>()) {
            owner->lock.onError(js, err.getHandle(js));
          }
        }
      }

      return result;
    }
    return false;
  }

  kj::Maybe<int> getDesiredSize() {
    KJ_IF_SOME(s, state) {
      return s.controller->getDesiredSize();
    }
    return kj::none;
  }

  bool canCloseOrEnqueue() {
    return state.map([](State& s) { return s.controller->canCloseOrEnqueue(); }).orDefault(false);
  }

  kj::Maybe<DefaultController> getControllerRef() {
    return state.map([](State& s) { return s.controller.addRef(); });
  }
};

struct ByteReadable final: public kj::PtrTarget,
                           public api::ByteQueue::ConsumerImpl::StateListener {

  using State = ReadableState<ByobController, ByteQueue>;
  kj::Maybe<State> state;
  kj::Maybe<int> autoAllocateChunkSize;
  bool reading = false;
  bool pendingCancel = false;

  JSG_MEMORY_INFO(ByteReadable) {
    KJ_IF_SOME(s, state) {
      tracker.trackField("controller", s.controller);
      tracker.trackField("consumer", s.consumer);
    }
  }

  void visitForGc(jsg::GcVisitor& visitor) {
    KJ_IF_SOME(s, state) {
      visitor.visit(s.controller, *s.consumer);
    }
  }

  ByteReadable(ByobController controller,
      kj::Ptr<ReadableStreamJsController> owner,
      kj::Maybe<int> autoAllocateChunkSize)
      : state(State(kj::mv(controller), addWeakToThis(), kj::mv(owner))),
        autoAllocateChunkSize(autoAllocateChunkSize) {}

  ByteReadable(jsg::Lock& js, kj::Ptr<ReadableStreamJsController> owner, ByteReadable& other)
      : state(KJ_ASSERT_NONNULL(other.state).clone(js, addWeakToThis(), kj::mv(owner))),
        autoAllocateChunkSize(other.autoAllocateChunkSize) {}

  KJ_DISALLOW_COPY_AND_MOVE(ByteReadable);

  void cancelPendingReads(jsg::Lock& js, jsg::JsValue reason) {
    KJ_IF_SOME(s, state) {
      s.consumer->cancelPendingReads(js, reason);
    }
  }

  // A single ReadableByteStreamController can have multiple consumers.
  // When the ByteReadable constructor is used, the new consumer is added
  // and starts to receive new data that becomes enqueued. When clone
  // is used, any state currently held by this consumer is copied to the
  // new consumer.
  kj::Own<ByteReadable> clone(jsg::Lock& js, kj::Ptr<ReadableStreamJsController> owner) {
    return kj::heap<ByteReadable>(js, kj::mv(owner), *this);
  }

  jsg::Promise<ReadResult> read(
      jsg::Lock& js, kj::Maybe<ReadableStreamController::ByobOptions> byobOptions) {
    KJ_IF_SOME(s, state) {
      auto prp = js.newPromiseAndResolver<ReadResult>();

      // Set reading = true to prevent cancel() from destroying the consumer
      // while we're in the middle of a synchronous read operation. The pull()
      // callback triggered by consumer->read() may call reader.cancel(), which
      // would otherwise immediately set state = kj::none and free the consumer.
      // KJ_DEFER ensures the flag is cleared even if an operation throws.
      reading = true;
      KJ_DEFER(reading = false);
      KJ_IF_SOME(byob, byobOptions) {
        auto view = byob.bufferView.getHandle(js);
        view = view.detachAndTake(js);
        size_t elementSize = view.getElementSize();
        // If atLeast is not given, then by default it is the element size of the view
        // that we were given. If atLeast is given, we make sure that it is aligned
        // with the element size. No matter what, atLeast cannot be less than 1.
        auto atLeast = kj::max(elementSize, byob.atLeast.orDefault(1));
        atLeast = kj::max(1, atLeast - (atLeast % elementSize));
        s.consumer->read(js,
            kj::heap<ByteQueue::ReadRequest>(kj::mv(prp.resolver),
                ByteQueue::ReadRequest::PullInto{
                  .view = view.addRef(js),
                  .elementSize = elementSize,
                  .originalOffset = view.getOffset(),
                  .atLeast = atLeast,
                  .type = ByteQueue::ReadRequest::Type::BYOB,
                }));
      } else KJ_IF_SOME(chunkSize, autoAllocateChunkSize) {
        // autoAllocateChunkSize is set, so we allocate a buffer and do a BYOB read.
        // This makes the buffer available to the underlying source via controller.byobRequest.
        KJ_IF_SOME(store, jsg::JsUint8Array::tryCreate(js, chunkSize)) {
          // Ensure that the handle is created here so that the size of the buffer
          // is accounted for in the isolate memory tracking.
          s.consumer->read(js,
              kj::heap<ByteQueue::ReadRequest>(kj::mv(prp.resolver),
                  ByteQueue::ReadRequest::PullInto{
                    .view = jsg::JsArrayBufferView(store).addRef(js),
                    .elementSize = 1,
                    .originalOffset = 0,
                    .type = ByteQueue::ReadRequest::Type::BYOB,
                  }));
        } else {
          prp.resolver.reject(js, js.error("Failed to allocate buffer for read."));
        }
      } else {
        // autoAllocateChunkSize is not set. Per spec, we do a DEFAULT read which means
        // the underlying source's pull method won't get a byobRequest. It must use
        // controller.enqueue() to provide data instead.
        constexpr size_t kDefaultReadSize = 16384;  // 16KB default buffer
        KJ_IF_SOME(store, jsg::JsUint8Array::tryCreate(js, kDefaultReadSize)) {
          s.consumer->read(js,
              kj::heap<ByteQueue::ReadRequest>(kj::mv(prp.resolver),
                  ByteQueue::ReadRequest::PullInto{
                    .view = jsg::JsArrayBufferView(store).addRef(js),
                    .elementSize = 1,
                    .originalOffset = 0,
                    .type = ByteQueue::ReadRequest::Type::DEFAULT,
                  }));
        } else {
          prp.resolver.reject(js, js.error("Failed to allocate buffer for read."));
        }
      }
      // reading is reset by KJ_DEFER above.
      if (pendingCancel) {
        // If we were canceled while reading, we need to drop our state now.
        state = kj::none;
        pendingCancel = false;
      }

      return kj::mv(prp.promise);
    }

    // We are canceled! There's nothing else to do.
    KJ_IF_SOME(byob, byobOptions) {
      // If a BYOB buffer was given, we need to give it back wrapped in a TypedArray
      // whose size is set to zero.
      auto view = jsg::JsArrayBufferView(byob.bufferView.getHandle(js));
      view = view.detachAndTake(js).slice(js, 0, 0);
      return js.resolvedPromise(ReadResult{
        .value = jsg::JsValue(view).addRef(js),
        .done = true,
      });
    } else {
      return js.resolvedPromise(ReadResult{.done = true});
    }
  }

  jsg::Promise<DrainingReadResult> drainingRead(jsg::Lock& js, size_t maxRead) {
    KJ_IF_SOME(s, state) {
      // Note: We do NOT call beginOperation()/endOperation() here. The caller
      // (ReadableStreamJsController::drainingRead) manages the operation scope
      // around both this call and the returned promise's lifetime. See the
      // comment in ValueReadable::drainingRead for the detailed explanation.
      return s.consumer->drainingRead(js, maxRead);
    }

    // We are canceled! Return done with empty chunks.
    return js.resolvedPromise(DrainingReadResult{
      .chunks = kj::Array<kj::Array<kj::byte>>(),
      .done = true,
    });
  }

  // When a ReadableStream is canceled, the expected behavior is that the underlying
  // controller is notified and the cancel algorithm on the underlying source is
  // called. When there are multiple ReadableStreams sharing consumption of a
  // controller, however, it should act as a shared pointer of sorts, canceling
  // the underlying controller only when the last reader is canceled.
  // Here, we rely on the controller implementing the correct behavior since it owns
  // the queue that knows about all of the attached consumers.
  jsg::Promise<void> cancel(jsg::Lock& js, jsg::Optional<jsg::JsValue> maybeReason) {
    if (pendingCancel) return js.resolvedPromise();
    KJ_IF_SOME(s, state) {
      // Check if there's a pending draining read before calling cancel, since cancel
      // will resolve the pending read and we need to know if we should defer destruction.
      bool hasPendingDrainingRead = s.consumer->hasPendingDrainingRead();
      s.consumer->cancel(js, maybeReason);
      auto promise = s.controller->cancel(js, maybeReason);
      // If we're currently in a read (sync or draining), we need to wait for that to
      // finish before dropping our state. For sync reads, consumer->read() is still on
      // the call stack and will access the consumer after we return. For draining reads,
      // the promise callbacks capture 'this' (the Consumer) to clear hasPendingDrainingRead.
      // In either case, destroying state now would UAF.
      if (reading || hasPendingDrainingRead) {
        pendingCancel = true;
      } else {
        state = kj::none;
      }
      return kj::mv(promise);
    }

    return js.resolvedPromise();
  }

  void onConsumerClose(jsg::Lock& js) override {
    // Note that the owner may drop this readable in doClose so it
    // is not safe to access anything on this after calling doClose.
    KJ_IF_SOME(s, state) {
      s.owner->doClose(js);
    }
  }

  void onConsumerError(jsg::Lock& js, jsg::JsValue reason) override {
    // Note that the owner may drop this readable in doClose so it
    // is not safe to access anything on this after calling doError.
    KJ_IF_SOME(s, state) {
      s.owner->doError(js, reason);
    };
  }

  // Called by the consumer when it has a queued pending read and needs
  // data to be provided to fulfill it. We need to notify the controller
  // to initiate pulling to provide the data.
  // Returns true if the pull completed synchronously (meaning more pumping
  // might yield additional synchronous data), false otherwise.
  bool onConsumerWantsData(jsg::Lock& js) override {
    KJ_IF_SOME(s, state) {
      // Save a COPY of the owner Ptr before calling pull — not a reference to the
      // member, which dies with `this`. The pull callback may trigger close/error
      // which could destroy this ByteReadable. By using beginOperation(), we ensure
      // doClose/doError defers the actual destruction until after we return. The
      // owner itself outlives us: only the owner can drop this ByteReadable.
      auto owner = s.owner;
      owner->state.beginOperation();

      // For draining reads, use forcePull to bypass backpressure checks.
      // This ensures we pull all available data regardless of highWaterMark.
      if (s.consumer->hasPendingDrainingRead()) {
        s.controller->forcePull(js);
      } else {
        s.controller->pull(js);
      }

      // Check if state is still valid BEFORE calling endOperation(),
      // because that call may destroy this ByteReadable if close was deferred.
      bool result =
          state.map([](State& s2) { return !s2.controller->isPulling(); }).orDefault(false);

      // Process any deferred close/error. This may destroy this ByteReadable.
      if (owner->state.endOperation()) {
        // A pending state was applied. Call the appropriate callback.
        if (owner->state.template is<StreamStates::Closed>()) {
          owner->lock.onClose(js);
        } else if (owner->state.template is<StreamStates::Errored>()) {
          KJ_IF_SOME(err, owner->state.template tryGetUnsafe<StreamStates::Errored>()) {
            owner->lock.onError(js, err.getHandle(js));
          }
        }
      }

      return result;
    }
    return false;
  }

  kj::Maybe<int> getDesiredSize() {
    KJ_IF_SOME(s, state) {
      return s.controller->getDesiredSize();
    }
    return kj::none;
  }

  bool canCloseOrEnqueue() {
    return state.map([](State& s) { return s.controller->canCloseOrEnqueue(); }).orDefault(false);
  }

  kj::Maybe<ByobController> getControllerRef() {
    return state.map([](State& state) { return state.controller.addRef(); });
  }
};
