ReadableStreamJsController::ReadableStreamJsController(): ioContext(tryGetIoContextId()) {}

ReadableStreamJsController::ReadableStreamJsController(StreamStates::Closed closed)
    : ioContext(tryGetIoContextId()) {
  state.transitionTo<StreamStates::Closed>();
}

ReadableStreamJsController::ReadableStreamJsController(StreamStates::Errored errored)
    : ioContext(tryGetIoContextId()) {
  state.transitionTo<StreamStates::Errored>(kj::mv(errored));
}

ReadableStreamJsController::ReadableStreamJsController(jsg::Lock& js, ValueReadable& consumer)
    : ioContext(tryGetIoContextId()) {
  state.transitionTo<kj::Own<ValueReadable>>(consumer.clone(js, addPtrToThis()));
}

ReadableStreamJsController::ReadableStreamJsController(jsg::Lock& js, ByteReadable& consumer)
    : ioContext(tryGetIoContextId()) {
  state.transitionTo<kj::Own<ByteReadable>>(consumer.clone(js, addPtrToThis()));
}

jsg::Ref<ReadableStream> ReadableStreamJsController::addRef() {
  return owner.assertLive().addRef();
}

jsg::Promise<void> ReadableStreamJsController::cancel(
    jsg::Lock& js, jsg::Optional<jsg::JsValue> maybeReason) {
  disturbed = true;

  const auto doCancel = [&](auto& consumer) {
    auto reason = maybeReason.orDefault([&] { return js.undefined(); });
    // consumer->cancel() invokes the user's cancel callback synchronously, and that callback can
    // reach any API that closes this stream — notably tee(). Closing destroys the consumer whose
    // cancel() is on the stack, so run this as an operation: state transitions are queued rather
    // than applied under us.
    state.beginOperation();
    KJ_DEFER({
      // endOperation() applies a queued transition if there is one. Whoever applies it owes the
      // lock the matching notification, since doClose()/doError() skip it when they defer.
      if (state.endOperation()) {
        // Skip callbacks if execution is being terminated (e.g. CPU time limit) since we can't
        // safely execute JavaScript in that state.
        if (!js.v8Isolate->IsExecutionTerminating()) {
          if (state.is<StreamStates::Closed>()) {
            lock.onClose(js);
          } else if (state.isErrored()) {
            lock.onError(js, state.getErrorUnsafe().getHandle(js));
          }
        }
      } else {
        // Nothing was queued, so close the stream here.
        doClose(js);
      }
    });
    return consumer->cancel(js, reason);
  };

  // Check for pending state first (deferred close/error during a read operation)
  if (state.pendingStateIs<StreamStates::Closed>()) {
    return js.resolvedPromise();
  }
  KJ_IF_SOME(pendingError, state.tryGetPendingStateUnsafe<StreamStates::Errored>()) {
    return js.rejectedPromise<void>(pendingError.getHandle(js));
  }

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Stream not yet set up, treat as closed.
      return js.resolvedPromise();
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return js.resolvedPromise();
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return js.rejectedPromise<void>(errored.getHandle(js));
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      if (canceling) return js.resolvedPromise();
      canceling = true;
      return doCancel(consumer);
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      if (canceling) return js.resolvedPromise();
      canceling = true;
      return doCancel(consumer);
    }
  }

  KJ_UNREACHABLE;
}

// Finalizes the closed state of this ReadableStream. The connection to the underlying
// controller is released with no further action. Importantly, this method is triggered
// by the underlying controller as a result of that controller closing or being canceled.
// We detach ourselves from the underlying controller by releasing the ValueReadable or
// ByteReadable in the state and changing that to closed.
// We also clean up other state here.
void ReadableStreamJsController::doClose(jsg::Lock& js) {
  // If already in a terminal state, nothing to do.
  if (state.isTerminal()) return;

  // deferTransitionTo will defer if an operation is in progress, otherwise transition immediately.
  // Returns true if transition happened immediately.
  if (state.deferTransitionTo<StreamStates::Closed>()) {
    lock.onClose(js);
  }
  // If deferred, lock.onClose will be called when the pending state is applied
  // via applyPendingState in deferControllerStateChange.
}

// As with doClose(), doError() finalizes the error state of this ReadableStream.
// The connection to the underlying controller is released with no further action.
// This method is triggered by the underlying controller as a result of that controller
// erroring. We detach ourselves from the underlying controller by releasing the ValueReadable
// or ByteReadable in the state and changing that to errored.
// We also clean up other state here.
void ReadableStreamJsController::doError(jsg::Lock& js, jsg::JsValue reason) {
  // If already in a terminal state, nothing to do.
  if (state.isTerminal()) return;

  // deferTransitionTo will defer if an operation is in progress, otherwise transition immediately.
  // Returns true if transition happened immediately.
  if (state.deferTransitionTo<StreamStates::Errored>(reason.addRef(js))) {
    lock.onError(js, reason);
  }
  // If deferred, lock.onError will be called when the pending state is applied
  // via applyPendingState in deferControllerStateChange.
}

bool ReadableStreamJsController::isByteOriented() const {
  return state.is<kj::Own<ByteReadable>>();
}

bool ReadableStreamJsController::isClosedOrErrored() const {
  // Check if we're in a terminal state or have one pending
  return state.isTerminal() || state.hasPendingState();
}

bool ReadableStreamJsController::isClosed() const {
  // Check current state first, then pending state
  if (state.is<StreamStates::Closed>()) return true;
  return state.pendingStateIs<StreamStates::Closed>();
}

bool ReadableStreamJsController::isDisturbed() {
  return disturbed;
}

bool ReadableStreamJsController::isLockedToReader() const {
  return lock.isLockedToReader();
}

bool ReadableStreamJsController::lockReader(jsg::Lock& js, kj::Ptr<Reader> reader) {
  return lock.lockReader(js, *this, reader);
}

jsg::Promise<void> ReadableStreamJsController::pipeTo(
    jsg::Lock& js, WritableStreamController& destination, PipeToOptions options) {
  KJ_DASSERT(!isLockedToReader());
  KJ_DASSERT(!destination.isLockedToWriter());

  disturbed = true;
  KJ_IF_SOME(promise, destination.tryPipeFrom(js, addRef(), kj::mv(options))) {
    return kj::mv(promise);
  }

  return js.rejectedPromise<void>(
      js.typeError("This ReadableStream cannot be piped to this WritableStream"_kj));
}

kj::Maybe<jsg::Promise<ReadResult>> ReadableStreamJsController::read(
    jsg::Lock& js, kj::Maybe<ByobOptions> maybeByobOptions) {
  disturbed = true;

  KJ_IF_SOME(byobOptions, maybeByobOptions) {
    byobOptions.detachBuffer = true;
    auto view = byobOptions.bufferView.getHandle(js);
    if (!view.isDetachable()) {
      return js.rejectedPromise<ReadResult>(
          js.typeError("Unabled to use non-detachable ArrayBuffer."_kj));
    }

    if (view.size() == 0) {
      return js.rejectedPromise<ReadResult>(
          js.typeError("Unable to use a zero-length ArrayBuffer."_kj));
    }

    // Check for pending error first (deferred error during a prior read operation)
    KJ_IF_SOME(pendingError, state.tryGetPendingStateUnsafe<StreamStates::Errored>()) {
      return js.rejectedPromise<ReadResult>(pendingError.getHandle(js));
    }

    if (state.is<StreamStates::Closed>() || state.pendingStateIs<StreamStates::Closed>()) {
      // If it is a BYOB read, then the spec requires that we return an empty
      // view of the same type provided, that uses the same backing memory
      // as that provided, but with zero-length.
      view = view.detachAndTake(js).slice(js, 0, 0);
      return js.resolvedPromise(ReadResult{
        .value = jsg::JsValue(view).addRef(js),
        .done = true,
      });
    }
  }

  // Check for pending state (deferred close/error during a prior read operation)
  if (state.pendingStateIs<StreamStates::Closed>()) {
    // The closed state for BYOB reads is handled in the maybeByobOptions check above.
    KJ_ASSERT(maybeByobOptions == kj::none);
    return js.resolvedPromise(ReadResult{.done = true});
  }
  KJ_IF_SOME(pendingError, state.tryGetPendingStateUnsafe<StreamStates::Errored>()) {
    return js.rejectedPromise<ReadResult>(pendingError.getHandle(js));
  }

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Stream not yet set up, treat as closed.
      KJ_ASSERT(maybeByobOptions == kj::none);
      return js.resolvedPromise(ReadResult{.done = true});
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      // The closed state for BYOB reads is handled in the maybeByobOptions check above.
      KJ_ASSERT(maybeByobOptions == kj::none);
      return js.resolvedPromise(ReadResult{.done = true});
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return js.rejectedPromise<ReadResult>(errored.getHandle(js));
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      // The ReadableStreamDefaultController does not support ByobOptions.
      // It should never happen, but let's make sure.
      KJ_ASSERT(maybeByobOptions == kj::none);
      return deferControllerStateChange(js, *this, [&]() mutable { return consumer->read(js); });
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      return deferControllerStateChange(
          js, *this, [&]() mutable { return consumer->read(js, kj::mv(maybeByobOptions)); });
    }
  }
  KJ_UNREACHABLE;
}

kj::Maybe<jsg::Promise<DrainingReadResult>> ReadableStreamJsController::drainingRead(
    jsg::Lock& js, size_t maxRead) {
  disturbed = true;

  // Check for pending state first (deferred close/error during a prior read operation)
  if (state.pendingStateIs<StreamStates::Closed>()) {
    return js.resolvedPromise(DrainingReadResult{
      .chunks = kj::Array<kj::Array<kj::byte>>(),
      .done = true,
    });
  }
  KJ_IF_SOME(pendingError, state.tryGetPendingStateUnsafe<StreamStates::Errored>()) {
    return js.rejectedPromise<DrainingReadResult>(pendingError.getHandle(js));
  }

  // Like deferControllerStateChange for regular reads, we need to prevent the controller
  // state from being destroyed while a draining read's promise callbacks are pending.
  // The drainingRead implementation captures `this` (the Consumer) in promise lambdas to
  // clear hasPendingDrainingRead. If the state is changed (destroying the Consumer) before
  // those callbacks run, we get a use-after-free.
  //
  // CRITICAL: state.beginOperation() MUST be called BEFORE consumer->drainingRead(), not
  // after. The consumer->drainingRead() call may trigger onConsumerWantsData -> forcePull
  // -> close/error, which calls deferTransitionTo. If no operation is in progress at that
  // point, the transition fires immediately, destroying the Consumer while we're still
  // inside its method and before the returned promise's .then() callbacks are set up.
  // The endOperation() happens in the .then() callbacks below, ensuring the deferred
  // state change only fires after the promise resolves/rejects and the Consumer's
  // this-capturing callbacks have already run.
  auto wrapDrainingRead =
      [this](jsg::Lock& js, jsg::Promise<DrainingReadResult> promise,
          jsg::Ref<ReadableStream> ref) mutable -> jsg::Promise<DrainingReadResult> {
    return promise.then(js, [this, ref = ref.addRef()](jsg::Lock& js, DrainingReadResult result) {
      if (state.endOperation()) {
        // A pending state was applied. Call the appropriate callback.
        if (state.template is<StreamStates::Closed>()) {
          lock.onClose(js);
        } else if (state.template is<StreamStates::Errored>()) {
          KJ_IF_SOME(err, state.template tryGetUnsafe<StreamStates::Errored>()) {
            lock.onError(js, err.getHandle(js));
            // The error was applied during this operation — the data we collected
            // may be invalid. Discard it and propagate the error rather than
            // silently returning possibly-corrupt data.
            js.throwException(err.getHandle(js));
          }
        }
      }
      return kj::mv(result);
    }, [this, ref = ref.addRef()](jsg::Lock& js, jsg::Value exception) -> DrainingReadResult {
      state.clearPendingState();
      (void)state.endOperation();
      js.throwException(kj::mv(exception));
    });
  };

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Stream not yet set up, treat as closed.
      return js.resolvedPromise(DrainingReadResult{
        .chunks = kj::Array<kj::Array<kj::byte>>(),
        .done = true,
      });
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return js.resolvedPromise(DrainingReadResult{
        .chunks = kj::Array<kj::Array<kj::byte>>(),
        .done = true,
      });
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return js.rejectedPromise<DrainingReadResult>(errored.getHandle(js));
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      // beginOperation MUST be before consumer->drainingRead() — see comment above.
      state.beginOperation();
      JSG_TRY(js) {
        return wrapDrainingRead(js, consumer->drainingRead(js, maxRead), addRef());
      }
      JSG_CATCH(exception) {
        state.clearPendingState();
        (void)state.endOperation();
        auto error = jsg::JsValue(exception.getHandle(js));
        doError(js, error);
        return js.rejectedPromise<DrainingReadResult>(error);
      };
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      // beginOperation MUST be before consumer->drainingRead() — see comment above.
      state.beginOperation();
      JSG_TRY(js) {
        return wrapDrainingRead(js, consumer->drainingRead(js, maxRead), addRef());
      }
      JSG_CATCH(exception) {
        state.clearPendingState();
        (void)state.endOperation();
        auto error = jsg::JsValue(exception.getHandle(js));
        doError(js, error);
        return js.rejectedPromise<DrainingReadResult>(error);
      };
    }
  }
  KJ_UNREACHABLE;
}

void ReadableStreamJsController::releaseReader(
    kj::Ptr<Reader> reader, kj::Maybe<jsg::Lock&> maybeJs) {
  lock.releaseReader(*this, kj::mv(reader), maybeJs);
}

ReadableStreamController::Tee ReadableStreamJsController::tee(jsg::Lock& js) {
  JSG_REQUIRE(!isLockedToReader(), TypeError, "This ReadableStream is locked to a reader.");
  lock.state.transitionTo<Locked>();
  disturbed = true;

  // This will leave this stream locked, disturbed, and closed.

  // Check for pending state first (deferred close/error during a prior read operation)
  if (state.pendingStateIs<StreamStates::Closed>()) {
    return Tee{
      .branch1 =
          js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(StreamStates::Closed())),
      .branch2 =
          js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(StreamStates::Closed())),
    };
  }
  KJ_IF_SOME(pendingError, state.tryGetPendingStateUnsafe<StreamStates::Errored>()) {
    return Tee{
      .branch1 =
          js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(pendingError.addRef(js))),
      .branch2 =
          js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(pendingError.addRef(js))),
    };
  }

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Stream not yet set up, treat as closed.
      return Tee{
        .branch1 =
            js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(StreamStates::Closed())),
        .branch2 =
            js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(StreamStates::Closed())),
      };
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return Tee{
        .branch1 =
            js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(StreamStates::Closed())),
        .branch2 =
            js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(StreamStates::Closed())),
      };
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return Tee{
        .branch1 =
            js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(errored.addRef(js))),
        .branch2 =
            js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(errored.addRef(js))),
      };
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      // Closing this stream destroys the consumer. tee() is reachable re-entrantly from a user
      // pull() callback invoked while a read is in progress, and that consumer is then still on
      // the stack in onConsumerWantsData(). deferTransitionTo() queues the transition until the
      // enclosing operation ends; with no operation in progress it transitions immediately.
      KJ_DEFER((void)state.deferTransitionTo<StreamStates::Closed>());
      // We create two additional streams that clone this stream's consumer state,
      // then close this stream's consumer.
      return Tee{
        .branch1 = js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(js, *consumer)),
        .branch2 = js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(js, *consumer)),
      };
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      // Same rationale as the ValueReadable case above.
      KJ_DEFER((void)state.deferTransitionTo<StreamStates::Closed>());
      // We create two additional streams that clone this stream's consumer state,
      // then close this stream's consumer.
      return Tee{
        .branch1 = js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(js, *consumer)),
        .branch2 = js.alloc<ReadableStream>(kj::heap<ReadableStreamJsController>(js, *consumer)),
      };
    }
  }
  KJ_UNREACHABLE;
}

void ReadableStreamJsController::setOwnerRef(kj::Weak<ReadableStream> stream) {
  KJ_ASSERT(owner == nullptr);
  owner = kj::mv(stream);
}

void ReadableStreamJsController::setup(jsg::Lock& js,
    jsg::Optional<UnderlyingSource> maybeUnderlyingSource,
    jsg::Optional<StreamQueuingStrategy> maybeQueuingStrategy) {
  auto underlyingSource = kj::mv(maybeUnderlyingSource).orDefault({});
  auto queuingStrategy = kj::mv(maybeQueuingStrategy).orDefault({});
  auto type = underlyingSource.type.map([](kj::StringPtr s) { return s; }).orDefault(""_kj);

  expectedLength = underlyingSource.expectedLength;

  if (type == "bytes") {
    // Per spec, autoAllocateChunkSize should only be set if the user explicitly provides it.
    // If not set, the underlying source's pull method won't receive a byobRequest for
    // non-BYOB reads and must use controller.enqueue() instead.
    //
    // However, our original implementation always defaulted to 4096, so we need a compat flag
    // to control this behavior. Default to legacy behavior if flags aren't available.
    bool useSpecCompliantBehavior = false;
    KJ_IF_SOME(flags, FeatureFlags::tryGet(js)) {
      useSpecCompliantBehavior = flags.getNoAutoAllocateChunkSize();
    }

    kj::Maybe<int> autoAllocateChunkSize;
    if (useSpecCompliantBehavior) {
      // Spec-compliant: only set if user explicitly provides it
      autoAllocateChunkSize =
          underlyingSource.autoAllocateChunkSize.map([](int size) { return size; });
    } else {
      // Legacy behavior: apply a default autoAllocateChunkSize if not provided.
      auto defaultChunkSize = UnderlyingSource::DEFAULT_AUTO_ALLOCATE_CHUNK_SIZE;
      if (util::Autogate::isEnabled(util::AutogateKey::UPDATED_AUTO_ALLOCATE_CHUNK_SIZE)) {
        defaultChunkSize = UnderlyingSource::DEFAULT_AUTO_ALLOCATE_CHUNK_SIZE_2;
      }
      autoAllocateChunkSize = underlyingSource.autoAllocateChunkSize.orDefault(defaultChunkSize);
    }

    auto controller =
        js.alloc<ReadableByteStreamController>(kj::mv(underlyingSource), kj::mv(queuingStrategy));

    KJ_IF_SOME(chunkSize, autoAllocateChunkSize) {
      JSG_REQUIRE(chunkSize > 0, TypeError, "The autoAllocateChunkSize option cannot be zero.");
    }

    // We account for the memory usage of the ByteReadable and its controller together because
    // their lifetimes are identical (in practice) and memory accounting itself has a memory
    // overhead. The same applies to ValueReadable below.
    state.transitionTo<kj::Own<ByteReadable>>(
        kj::heap<ByteReadable>(controller.addRef(), addPtrToThis(), autoAllocateChunkSize)
            .attach(js.getExternalMemoryAdjustment(
                sizeof(ByteReadable) + sizeof(ReadableByteStreamController))));
    controller->start(js);
  } else {
    JSG_REQUIRE(
        type == "", TypeError, kj::str("\"", type, "\" is not a valid type of ReadableStream."));
    auto controller = js.alloc<ReadableStreamDefaultController>(
        kj::mv(underlyingSource), kj::mv(queuingStrategy));
    state.transitionTo<kj::Own<ValueReadable>>(
        kj::heap<ValueReadable>(controller.addRef(), addPtrToThis())
            .attach(js.getExternalMemoryAdjustment(
                sizeof(ValueReadable) + sizeof(ReadableStreamDefaultController))));
    controller->start(js);
  }
}

kj::Maybe<kj::Ptr<ReadableStreamController::PipeController>> ReadableStreamJsController::
    tryPipeLock() {
  return lock.tryPipeLock(addPtrToThis());
}

void ReadableStreamJsController::releasePipeLock(
    jsg::Lock& js, kj::Maybe<jsg::JsValue> maybeError) {
  lock.releasePipeLock(*this, js, maybeError);
}

void ReadableStreamJsController::visitForGc(jsg::GcVisitor& visitor) {
  // Visit pending state if it's an error (Closed has no GC-traceable content)
  KJ_IF_SOME(pendingError, state.tryGetPendingStateUnsafe<StreamStates::Errored>()) {
    visitor.visit(pendingError);
  }

  // Note: We cannot use state.visitForGc(visitor) here because the state machine's
  // visitForGc passes kj::Own<T>& to visitor.visit(), but GcVisitor expects T& for
  // types with visitForGc methods. We must dereference kj::Own manually.
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {}
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {}
    KJ_CASE_ONEOF(error, StreamStates::Errored) {
      visitor.visit(error);
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      visitor.visit(*consumer);
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      visitor.visit(*consumer);
    }
  }
  visitor.visit(lock);
}

kj::Maybe<int> ReadableStreamJsController::getDesiredSize() {
  // If there's a pending state transition, return none
  if (state.hasPendingState()) {
    return kj::none;
  }

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      return kj::none;
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return kj::none;
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return kj::none;
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      return consumer->getDesiredSize();
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      return consumer->getDesiredSize();
    }
  }
  KJ_UNREACHABLE;
}

kj::Maybe<jsg::JsValue> ReadableStreamJsController::isErrored(jsg::Lock& js) {
  // Check for pending error first
  KJ_IF_SOME(pendingError, state.tryGetPendingStateUnsafe<StreamStates::Errored>()) {
    return pendingError.getHandle(js);
  }
  // Pending Closed means not errored, so we can just check current state
  return state.tryGetUnsafe<StreamStates::Errored>().map(
      [&](jsg::JsRef<jsg::JsValue>& reason) { return reason.getHandle(js); });
}

bool ReadableStreamJsController::canCloseOrEnqueue() {
  // If there's a pending state transition, can't close or enqueue
  if (state.hasPendingState()) {
    return false;
  }

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      return false;
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return false;
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return false;
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      return consumer->canCloseOrEnqueue();
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      return consumer->canCloseOrEnqueue();
    }
  }
  KJ_UNREACHABLE;
}

bool ReadableStreamJsController::hasBackpressure() {
  KJ_IF_SOME(size, getDesiredSize()) {
    return size <= 0;
  }
  return false;
}

kj::Maybe<kj::OneOf<DefaultController, ByobController>> ReadableStreamJsController::
    getController() {
  // If there's a pending state transition, return none
  if (state.hasPendingState()) {
    return kj::none;
  }
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      return kj::none;
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return kj::none;
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return kj::none;
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ValueReadable>) {
      return consumer->getControllerRef();
    }
    KJ_CASE_ONEOF(consumer, kj::Own<ByteReadable>) {
      return consumer->getControllerRef();
    }
  }
  KJ_UNREACHABLE;
}

WD_STRONG_BOOL(StripBom);
namespace {
// Consumes all bytes from a stream, buffering in memory, with the purpose
// of producing either a single concatenated kj::Array<byte> or kj::String.
class AllReader {
 public:
  using PartList = kj::Array<kj::Array<kj::byte>>;

  AllReader(jsg::Ref<ReadableStream> stream, uint64_t limit)
      : state(State::create<jsg::Ref<ReadableStream>>(kj::mv(stream))),
        limit(limit) {}
  KJ_DISALLOW_COPY_AND_MOVE(AllReader);

  jsg::Promise<jsg::JsRef<jsg::JsArrayBuffer>> allBytes(jsg::Lock& js) {
    return loop(js).then(js, [this](auto& js, PartList partPtrs) -> jsg::JsRef<jsg::JsArrayBuffer> {
      auto ab = jsg::JsArrayBuffer::create(js, runningTotal);
      copyInto(ab.asArrayPtr(), partPtrs);
      return ab.addRef(js);
    });
  }

  jsg::Promise<kj::String> allText(
      jsg::Lock& js, ReadAllTextOption option = ReadAllTextOption::NULL_TERMINATE) {
    return loop(js).then(js, [this, option](auto& js, PartList partPtrs) {
      // Strip UTF-8 BOM if requested
      bool hadBom = false;
      if ((option & ReadAllTextOption::STRIP_BOM) && partPtrs.size() > 0 &&
          hasUtf8Bom(partPtrs[0])) {
        runningTotal -= UTF8_BOM_SIZE;
        hadBom = true;
      }

      JSG_REQUIRE(runningTotal <= v8::String::kMaxLength, RangeError,
          "String length exceeds v8::String::kMaxLength.");

      auto out = kj::heapArray<char>(runningTotal + 1);
      copyInto(
          out.first(out.size() - 1).asBytes(), partPtrs, hadBom ? StripBom::YES : StripBom::NO);
      out.back() = '\0';
      return kj::String(kj::mv(out));
    });
  }

  void visitForGc(jsg::GcVisitor& visitor) {
    state.visitForGc(visitor);
  }

 private:
  // State machine for AllReader:
  // Closed is terminal, Errored is implicitly terminal via ErrorState.
  // jsg::Ref<ReadableStream> is the active state (still reading).
  using State = StateMachine<TerminalStates<StreamStates::Closed>,
      ErrorState<StreamStates::Errored>,
      ActiveState<jsg::Ref<ReadableStream>>,
      StreamStates::Closed,
      StreamStates::Errored,
      jsg::Ref<ReadableStream>>;
  State state;
  uint64_t limit;
  kj::Vector<kj::Array<kj::byte>> parts;
  uint64_t runningTotal = 0;

  jsg::Promise<PartList> loop(jsg::Lock& js) {
    KJ_SWITCH_ONEOF(state) {
      KJ_CASE_ONEOF(closed, StreamStates::Closed) {
        return js.resolvedPromise(parts.releaseAsArray());
      }
      KJ_CASE_ONEOF(errored, StreamStates::Errored) {
        return js.template rejectedPromise<PartList>(errored.getHandle(js));
      }
      KJ_CASE_ONEOF(readable, jsg::Ref<ReadableStream>) {
        // Note that these nested lambda retain references to `this` and `readable`
        // and are passed into to promise returned by this method. It is the responsibility
        // of the caller to ensure that the AllReader instance is kept alive until the
        // promise is settled.
        auto onSuccess = [this, readable = readable.addRef()](
                             jsg::Lock& js, ReadResult result) mutable -> jsg::Promise<PartList> {
          if (result.done) {
            state.template transitionTo<StreamStates::Closed>();
            return loop(js);
          }

          // If we're not done, the result value must be interpretable as
          // bytes for the read to make any sense.
          auto handle = KJ_ASSERT_NONNULL(result.value).getHandle(js);
          if (!handle.isArrayBufferView() && !handle.isArrayBuffer()) {
            auto error = js.typeError("This ReadableStream did not return bytes.");
            state.template transitionTo<StreamStates::Errored>(error.addRef(js));
            return readable->getController().cancel(js, error).then(
                js, [&](jsg::Lock& js) { return loop(js); });
          }

          auto bufferSource = jsg::JsBufferSource(handle);

          if (bufferSource.size() == 0) {
            // Weird but allowed, we'll skip it.
            return loop(js);
          }

          if ((runningTotal + bufferSource.size()) > limit) {
            auto error = js.typeError("Memory limit exceeded before EOF.");
            state.template transitionTo<StreamStates::Errored>(error.addRef(js));
            return readable->getController().cancel(js, error).then(
                js, [&](jsg::Lock& js) { return loop(js); });
          }

          runningTotal += bufferSource.size();
          // Unfortunately there is a double copy required (one here, and one
          // in copyInto). We need to defensively copy the bufferSource because
          // there's a chance user-code could detach, resize, or modify the
          // underlying ArrayBuffer after we return from the read. We don't
          // know how much data the stream will produce tho so we can't read
          // into a pre-allocated buffer for the final result. So we have to
          // copy once here, then copy again into the final result.
          // TODO(perf): Later, we can try optimizing this but for now we want
          // to be correct and safe.
          parts.add(bufferSource.copy());
          return loop(js);
        };

        auto onFailure = [this](auto& js, jsg::Value exception) -> jsg::Promise<PartList> {
          // In this case the stream should already be errored.
          auto error = jsg::JsValue(exception.getHandle(js));
          state.template transitionTo<StreamStates::Errored>(error.addRef(js));
          return loop(js);
        };

        return maybeAddFunctor(js, KJ_ASSERT_NONNULL(readable->getController().read(js, kj::none)),
            kj::mv(onSuccess), kj::mv(onFailure));
      }
    }
    KJ_UNREACHABLE;
  }

  void copyInto(
      kj::ArrayPtr<byte> out, kj::ArrayPtr<kj::Array<byte>> in, StripBom stripBom = StripBom::NO) {
    bool firstPart = true;
    for (auto& part: in) {
      // If requested, strip the UTF-8 BOM from the first part.
      // stripBom will only be set to YES if the caller has already
      // verified that the first part is non-empty and has the BOM
      if (stripBom && firstPart) {
        firstPart = false;
        auto partWithoutBom = part.slice(UTF8_BOM_SIZE);
        KJ_ASSERT(partWithoutBom.size() <= out.size());
        out.write(partWithoutBom);
      } else {
        KJ_ASSERT(part.size() <= out.size());
        out.write(part);
      }
    }
  }
};

// Hands `promise` off to a holder that outlives the caller, reporting its outcome
// through `fulfiller`. Fulfilling or rejecting a fulfiller whose promise is already
// gone is a no-op, so the caller is free to stop listening at any point.
template <typename T>
kj::Promise<void> forwardToFulfiller(
    kj::Promise<T> promise, kj::Own<kj::PromiseFulfiller<T>> fulfiller) {
  KJ_TRY {
    if constexpr (jsg::isVoid<T>()) {
      co_await promise;
      fulfiller->fulfill();
    } else {
      fulfiller->fulfill(co_await promise);
    }
  }
  KJ_CATCH(exception) {
    fulfiller->reject(kj::mv(exception));
  }
}

// pumpToImpl uses a DrainingReader to efficiently pull all synchronously available
// data from the stream in each iteration, then writes it to the sink using vectored
// I/O. This minimizes isolate lock acquisitions by batching: each time the lock is
// held, the stream's internal queue is fully drained and the JS pull callback is
// pumped synchronously as many times as possible.
//
// The pump loop is a kj coroutine. Dropping the returned kj::Promise drops the
// coroutine frame, which destroys the DrainingReader (releasing the stream lock)
// and the sink.
// The coroutine that implements the pump loop takes ownership of the DrainingReader
// and sink. The jsg::Ref<ReadableStream> is not passed into the coroutine because
// jsg::Ref is disallowed in coroutine parameters; instead, the DrainingReader holds
// a reference to the stream internally.
//
// Neither isolate-lock round trip below is awaited directly. A draining read runs
// the stream's pull() callback, and pull() can abort the request, which drops the
// pump promise from inside the very event that is delivering the read's result.
// Destroying an event while it is firing trips "Promise callback destroyed itself".
// Each run() is therefore handed to the IoContext's task set, and the pump awaits an
// unrelated fulfiller. Dropping the pump then destroys only that await; the firing
// event stays owned by the task set, which unwinds it once it is safe to.
//
// The consequence is that those tasks outlive the coroutine frame, so they must not
// name anything the frame owns. The DrainingReader is reached through a kj::Weak,
// which reports the frame's destruction rather than dangling into it.
kj::Promise<void> pumpToImpl(IoContext& ioContext,
    kj::Own<DrainingReader> reader,
    kj::Own<WritableStreamSink> sink,
    bool end) {

  bool writeFailed = false;

  KJ_TRY {
    while (true) {
      // Perform a draining read to get all synchronously available data if possible
      // or fall back to a regular read if not.
      auto prp = kj::newPromiseAndFulfiller<DrainingReadResult>();
      auto promise = ioContext.run([weakReader = reader->getWeak()](
                                       jsg::Lock& js) mutable -> kj::Promise<DrainingReadResult> {
        auto& ioContext = IoContext::current();
        KJ_IF_SOME(reader, weakReader.tryGet()) {
          // Use a 256KB limit to allow periodic yielding to the event loop,
          // preventing a fast producer from monopolizing the thread.
          constexpr size_t kMaxReadPerCycle = 256 * 1024;
          return ioContext.awaitJs(js, reader.read(js, kMaxReadPerCycle));
        } else {
          return KJ_EXCEPTION(DISCONNECTED, "The pump was canceled.");
        }
      });
      ioContext.addTask(forwardToFulfiller(kj::mv(promise), kj::mv(prp.fulfiller)));

      DrainingReadResult result = co_await prp.promise;

      // Write all the chunks we received using vectored write for efficiency.
      if (result.chunks.size() > 0) {
        KJ_ON_SCOPE_FAILURE(writeFailed = true);
        auto pieces =
            KJ_MAP(chunk, result.chunks) -> kj::ArrayPtr<const kj::byte> { return chunk.asPtr(); };
        co_await sink->write(pieces);
      }

      // If the stream is done, end the output if needed and exit.
      if (result.done) {
        KJ_ON_SCOPE_FAILURE(writeFailed = true);
        if (end) {
          co_await sink->end();
        }
        co_return;
      }
    }
  }
  KJ_CATCH(exception) {
    if (!writeFailed) {
      sink->abort(exception.clone());
    }

    auto prp = kj::newPromiseAndFulfiller<void>();
    auto promise = ioContext.run([weakReader = reader->getWeak(), ex = exception.clone()](
                                     jsg::Lock& js) mutable -> kj::Promise<void> {
      auto& ioContext = IoContext::current();
      KJ_IF_SOME(reader, weakReader.tryGet()) {
        auto error = js.exceptionToJsValue(kj::mv(ex));
        return ioContext.awaitJs(js, reader.cancel(js, error.getHandle(js)));
      } else {
        return KJ_EXCEPTION(DISCONNECTED, "The pump was canceled.");
      }
    });
    ioContext.addTask(forwardToFulfiller(kj::mv(promise), kj::mv(prp.fulfiller)));

    co_await prp.promise;
    kj::throwFatalException(kj::mv(exception));
  }
}
}  // namespace

template <typename T>
jsg::Promise<T> ReadableStreamJsController::readAll(jsg::Lock& js, uint64_t limit) {
  if (isLockedToReader()) {
    return js.rejectedPromise<T>(
        js.typeError("This ReadableStream is currently locked to a reader."));
  }
  disturbed = true;

  bool stripBom = false;
  KJ_IF_SOME(flags, FeatureFlags::tryGet(js)) {
    stripBom = flags.getStripBomInReadAllText();
  }

  // This operation leaves the stream locked and disturbed. The loop will read until
  // the stream is closed or errored. If the limit is reached, the loop will error.

  const auto readAll = [this, limit, stripBom](auto& js) -> jsg::Promise<T> {
    KJ_ASSERT(lock.lock());
    // The AllReader will hold a traceable reference to the ReadableStream.
    auto reader = kj::heap<AllReader>(addRef(), limit);

    auto promise = ([&js, &reader, stripBom]() -> jsg::Promise<T> {
      if constexpr (kj::isSameType<T, jsg::JsRef<jsg::JsArrayBuffer>>()) {
        (void)stripBom;  // Unused in this branch.
        return reader->allBytes(js);
      } else {
        auto option = ReadAllTextOption::NULL_TERMINATE;
        if (stripBom) {
          option |= ReadAllTextOption::STRIP_BOM;
        }
        return reader->allText(js, option);
      }
    })();

    return maybeAddFunctor(js, kj::mv(promise),
        // reader is a GC visitable type that holds a reference to either the stream
        // or an error. Accordingly, we wrap it in a visitable lambda attached as a
        // continuation on the promise to ensure that it is GC visited and kept alive until
        // the promise settles.
        [reader = kj::mv(reader)](jsg::Lock& js, T result) -> jsg::Promise<T> {
      return js.resolvedPromise(kj::mv(result));
    }, [](jsg::Lock& js, jsg::Value exception) -> jsg::Promise<T> {
      return js.rejectedPromise<T>(kj::mv(exception));
    });
  };

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Stream not yet set up, treat as closed.
      if constexpr (kj::isSameType<T, jsg::JsRef<jsg::JsArrayBuffer>>()) {
        auto ab = jsg::JsArrayBuffer::create(js, 0);
        return js.resolvedPromise(ab.addRef(js));
      } else {
        return js.resolvedPromise(T());
      }
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      if constexpr (kj::isSameType<T, jsg::JsRef<jsg::JsArrayBuffer>>()) {
        auto ab = jsg::JsArrayBuffer::create(js, 0);
        return js.resolvedPromise(ab.addRef(js));
      } else {
        return js.resolvedPromise(T());
      }
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return js.rejectedPromise<T>(errored.getHandle(js));
    }
    KJ_CASE_ONEOF(valueReadable, kj::Own<ValueReadable>) {
      return readAll(js);
    }
    KJ_CASE_ONEOF(byteReadable, kj::Own<ByteReadable>) {
      return readAll(js);
    }
  }
  KJ_UNREACHABLE;
}

jsg::Promise<jsg::JsRef<jsg::JsArrayBuffer>> ReadableStreamJsController::readAllBytes(
    jsg::Lock& js, uint64_t limit) {
  return readAll<jsg::JsRef<jsg::JsArrayBuffer>>(js, limit);
}

jsg::Promise<kj::String> ReadableStreamJsController::readAllText(jsg::Lock& js, uint64_t limit) {
  return readAll<kj::String>(js, limit);
}

kj::Own<ReadableStreamController> ReadableStreamJsController::detach(
    jsg::Lock& js, bool ignored /* unused */) {
  KJ_ASSERT(!isLockedToReader());
  KJ_ASSERT(!isDisturbed());
  KJ_ASSERT(!state.hasOperationInProgress(), "Unable to detach with read pending");
  auto controller = kj::heap<ReadableStreamJsController>();
  controller->expectedLength = expectedLength;
  disturbed = true;

  // Clones this streams state into a new ReadableStreamController, leaving this stream
  // locked, disturbed, and closed.

  // The controller starts in Initial state by default, so we can use regular transitionTo.
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Still in initial state, transition to closed
      controller->state.transitionTo<StreamStates::Closed>();
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      controller->state.transitionTo<StreamStates::Closed>();
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      controller->state.transitionTo<StreamStates::Errored>(errored.addRef(js));
    }
    KJ_CASE_ONEOF(readable, kj::Own<ValueReadable>) {
      KJ_ASSERT(lock.lock());
      controller->state.transitionTo<kj::Own<ValueReadable>>(
          readable->clone(js, controller->addPtrToThis()));
      state.transitionTo<StreamStates::Closed>();
      lock.onClose(js);
    }
    KJ_CASE_ONEOF(readable, kj::Own<ByteReadable>) {
      KJ_ASSERT(lock.lock());
      controller->state.transitionTo<kj::Own<ByteReadable>>(
          readable->clone(js, controller->addPtrToThis()));
      state.transitionTo<StreamStates::Closed>();
      lock.onClose(js);
    }
  }

  return kj::mv(controller);
}

kj::Maybe<uint64_t> ReadableStreamJsController::tryGetLength(StreamEncoding encoding) {
  return expectedLength;
}

kj::Promise<DeferredProxy<void>> ReadableStreamJsController::pumpTo(
    jsg::Lock& js, kj::Own<WritableStreamSink> sink, bool end) {
  KJ_ASSERT(IoContext::hasCurrent(), "Unable to consume this ReadableStream outside of a request");
  KJ_REQUIRE(!isLockedToReader(), "This ReadableStream is currently locked to a reader.");
  disturbed = true;

  // This operation will leave the ReadableStream locked and disturbed. It will consume
  // the stream until it either closed or errors.
  //
  const auto handlePump = [&] {
    auto reader = KJ_ASSERT_NONNULL(DrainingReader::create(js, *this->addRef()),
        "Failed to create DrainingReader — stream should not be locked");
    auto& ioContext = IoContext::current();
    return addNoopDeferredProxy(pumpToImpl(ioContext, kj::mv(reader), kj::mv(sink), end));
  };

  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Stream not yet set up, treat as closed.
      return addNoopDeferredProxy(sink->end().attach(kj::mv(sink)));
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return addNoopDeferredProxy(sink->end().attach(kj::mv(sink)));
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return js.exceptionToKj(errored.addRef(js));
    }
    KJ_CASE_ONEOF(readable, kj::Own<ValueReadable>) {
      return handlePump();
    }
    KJ_CASE_ONEOF(readable, kj::Own<ByteReadable>) {
      return handlePump();
    }
  }

  KJ_UNREACHABLE;
}

