// ======================================================================================
WritableStreamJsController::WritableStreamJsController(): ioContext(tryGetIoContextId()) {}

WritableStreamJsController::~WritableStreamJsController() noexcept(false) {
  // Clear algorithms to break circular references during destruction
  KJ_IF_SOME(controller, state.tryGetUnsafe<Controller>()) {
    controller->clearAlgorithms();
  }
  // Clear the state to break the circular reference to the controller.
  // During destruction, we force the transition since the current state doesn't matter.
  state.forceTransitionTo<StreamStates::Closed>();
  // Clear any pending abort promise
  maybeAbortPromise = kj::none;
}

WritableStreamJsController::WritableStreamJsController(StreamStates::Closed closed)
    : ioContext(tryGetIoContextId()) {
  state.transitionTo<StreamStates::Closed>();
}

WritableStreamJsController::WritableStreamJsController(StreamStates::Errored errored)
    : ioContext(tryGetIoContextId()) {
  state.transitionTo<StreamStates::Errored>(kj::mv(errored));
}

jsg::Promise<void> WritableStreamJsController::abort(
    jsg::Lock& js, jsg::Optional<jsg::JsValue> reason) {
  // The spec requires that if abort is called multiple times, it is supposed to return the same
  // promise each time. That's a bit cumbersome here with jsg::Promise so we intentionally just
  // return a continuation branch off the same promise.
  KJ_IF_SOME(abortPromise, maybeAbortPromise) {
    return abortPromise.whenResolved(js);
  }
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      // Stream hasn't been set up yet - treat like closed for abort purposes
      maybeAbortPromise = js.resolvedPromise();
      return KJ_ASSERT_NONNULL(maybeAbortPromise).whenResolved(js);
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      maybeAbortPromise = js.resolvedPromise();
      return KJ_ASSERT_NONNULL(maybeAbortPromise).whenResolved(js);
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      // Per the spec, if the stream is errored, we are to return a resolved promise.
      maybeAbortPromise = js.resolvedPromise();
      return KJ_ASSERT_NONNULL(maybeAbortPromise).whenResolved(js);
    }
    KJ_CASE_ONEOF(controller, Controller) {
      maybeAbortPromise = controller->abort(js, reason.orDefault(js.undefined()));
      return KJ_ASSERT_NONNULL(maybeAbortPromise).whenResolved(js);
    }
  }
  KJ_UNREACHABLE;
}

jsg::Ref<WritableStream> WritableStreamJsController::addRef() {
  return owner.assertLive().addRef();
}

bool WritableStreamJsController::isClosedOrClosing() {
  return state.is<StreamStates::Closed>();
}

bool WritableStreamJsController::isErrored() {
  return state.isErrored();
}

jsg::Promise<void> WritableStreamJsController::close(jsg::Lock& js, bool markAsHandled) {
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      return rejectedMaybeHandledPromise<void>(
          js, js.typeError("This WritableStream has been closed."_kj), markAsHandled);
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return rejectedMaybeHandledPromise<void>(
          js, js.typeError("This WritableStream has been closed."_kj), markAsHandled);
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      if (FeatureFlags::get(js).getPedanticWpt()) {
        return rejectedMaybeHandledPromise<void>(
            js, js.typeError("This WritableStream has been errored."_kj), markAsHandled);
      }
      return rejectedMaybeHandledPromise<void>(js, errored.getHandle(js), markAsHandled);
    }
    KJ_CASE_ONEOF(controller, Controller) {
      return controller->close(js);
    }
  }
  KJ_UNREACHABLE;
}

void WritableStreamJsController::doClose(jsg::Lock& js) {
  // If already in a terminal state, nothing to do.
  if (state.isTerminal()) return;

  // Clear algorithms to break circular references before changing state
  KJ_IF_SOME(controller, state.tryGetUnsafe<Controller>()) {
    controller->clearAlgorithms();
  }

  state.transitionTo<StreamStates::Closed>();
  KJ_IF_SOME(locked, lock.state.tryGetUnsafe<WriterLocked>()) {
    maybeResolvePromise(js, locked.getClosedFulfiller());
    maybeResolvePromise(js, locked.getReadyFulfiller());
  } else KJ_IF_SOME(pipeLocked, lock.state.tryGetUnsafe<WritableLockImpl::PipeLocked>()) {
    // The destination closed while a pipe holds the lock. This happens when a close was
    // already queued or in flight when the pipe started (the pipe loop's own close only
    // completes after the loop has released both locks). We must release the source's
    // pipe lock here; nothing else will: the pipe loop bails out as soon as the
    // write-side lock state is gone, and doError() never runs for a stream that reached
    // Closed. Closing propagates backward per the spec, so cancel the source unless
    // preventCancel. releaseSource() is idempotent, making this safe when the pipe's
    // write-failure path already released the source (a write rejected by the queued
    // close).
    if (!pipeLocked.flags.preventCancel) {
      pipeLocked.releaseSource(js, js.typeError("This destination writable stream is closed."_kj));
    } else {
      pipeLocked.releaseSource(js);
    }
    (void)lock.state.transitionFromTo<WritableLockImpl::PipeLocked, Unlocked>();
  }
}

void WritableStreamJsController::doError(jsg::Lock& js, jsg::JsValue reason) {
  // If already in a terminal state, nothing to do.
  if (state.isTerminal()) return;

  // Clear algorithms to break circular references before changing state
  KJ_IF_SOME(controller, state.tryGetUnsafe<Controller>()) {
    controller->clearAlgorithms();
  }

  state.transitionTo<StreamStates::Errored>(reason.addRef(js));
  KJ_IF_SOME(locked, lock.state.tryGetUnsafe<WriterLocked>()) {
    maybeRejectPromise<void>(js, locked.getClosedFulfiller(), reason);
    maybeResolvePromise(js, locked.getReadyFulfiller());
  } else KJ_IF_SOME(pipeLocked, lock.state.tryGetUnsafe<WritableLockImpl::PipeLocked>()) {
    // When the writable side of a pipe errors, we need to release the source stream.
    // The pipeLoop may be waiting on a read from the source that will never complete,
    // so we need to proactively release the source here.
    if (!pipeLocked.flags.preventCancel) {
      pipeLocked.releaseSource(js, reason);
    } else {
      pipeLocked.releaseSource(js);
    }
    (void)lock.state.transitionFromTo<WritableLockImpl::PipeLocked, Unlocked>();
  }
}

void WritableStreamJsController::errorIfNeeded(jsg::Lock& js, jsg::JsValue reason) {
  // Error through the underlying controller if available, which goes through the proper
  // error transition (Erroring -> Errored). This allows close() to be called while the
  // stream is "erroring" and reject with the stored error.
  KJ_IF_SOME(controller, state.tryGetUnsafe<Controller>()) {
    controller->error(js, reason);
  }
  // If state is not Controller (already Closed or Errored), this is a no-op.
}

kj::Maybe<int> WritableStreamJsController::getDesiredSize() {
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      return 0;
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return 0;
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return kj::none;
    }
    KJ_CASE_ONEOF(controller, Controller) {
      return controller->getDesiredSize().map([](ssize_t size) -> int { return size; });
    }
  }
  KJ_UNREACHABLE;
}

kj::Maybe<jsg::JsValue> WritableStreamJsController::isErroring(jsg::Lock& js) {
  KJ_IF_SOME(controller, state.tryGetUnsafe<Controller>()) {
    return controller->isErroring(js);
  }
  return kj::none;
}

bool WritableStreamDefaultController::isErroring() const {
  return impl.state.is<StreamStates::Erroring>();
}

kj::Maybe<jsg::JsValue> WritableStreamJsController::isErroredOrErroring(jsg::Lock& js) {
  KJ_IF_SOME(err, state.tryGetErrorUnsafe()) {
    return err.getHandle(js);
  }
  return isErroring(js);
}

bool WritableStreamJsController::isStarted() {
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      return false;
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return true;
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return true;
    }
    KJ_CASE_ONEOF(controller, Controller) {
      return controller->isStarted();
    }
  }
  KJ_UNREACHABLE;
}

bool WritableStreamJsController::hasBackpressure() {
  KJ_IF_SOME(controller, state.tryGetUnsafe<Controller>()) {
    return controller->hasBackpressure();
  }
  return false;
}

bool WritableStreamJsController::isLocked() const {
  return isLockedToWriter();
}

bool WritableStreamJsController::isLockedToWriter() const {
  return !lock.state.is<Unlocked>();
}

bool WritableStreamJsController::lockWriter(jsg::Lock& js, kj::Ptr<Writer> writer) {
  return lock.lockWriter(js, *this, kj::mv(writer));
}

void WritableStreamJsController::maybeRejectReadyPromise(jsg::Lock& js, jsg::JsValue reason) {
  KJ_IF_SOME(writerLock, lock.state.tryGetUnsafe<WriterLocked>()) {
    if (writerLock.getReadyFulfiller() != kj::none) {
      maybeRejectPromise<void>(js, writerLock.getReadyFulfiller(), reason);
    } else {
      auto prp = js.newPromiseAndResolver<void>();
      prp.promise.markAsHandled(js);
      prp.resolver.reject(js, reason);
      writerLock.setReadyFulfiller(js, prp);
    }
  }
}

void WritableStreamJsController::maybeResolveReadyPromise(jsg::Lock& js) {
  KJ_IF_SOME(writerLock, lock.state.tryGetUnsafe<WriterLocked>()) {
    maybeResolvePromise(js, writerLock.getReadyFulfiller());
  }
}

void WritableStreamJsController::releaseWriter(
    kj::Ptr<Writer> writer, kj::Maybe<jsg::Lock&> maybeJs) {
  lock.releaseWriter(*this, kj::mv(writer), maybeJs);
}

kj::Maybe<kj::Own<WritableStreamSink>> WritableStreamJsController::removeSink(jsg::Lock& js) {
  return kj::none;
}
void WritableStreamJsController::detach(jsg::Lock& js) {
  KJ_UNIMPLEMENTED("WritableStreamJsController::detach is not implemented");
}

void WritableStreamJsController::setOwnerRef(kj::Weak<WritableStream> stream) {
  owner = kj::mv(stream);
}

void WritableStreamJsController::setup(jsg::Lock& js,
    jsg::Optional<UnderlyingSink> maybeUnderlyingSink,
    jsg::Optional<StreamQueuingStrategy> maybeQueuingStrategy) {
  auto underlyingSink = kj::mv(maybeUnderlyingSink).orDefault({});
  auto queuingStrategy = kj::mv(maybeQueuingStrategy).orDefault({});

  if (FeatureFlags::get(js).getPedanticWpt()) {
    // Per the spec, the type property for WritableStream's underlying sink must be undefined.
    // If it's anything else, throw a RangeError.
    JSG_REQUIRE(underlyingSink.type == kj::none, RangeError,
        "Invalid underlying sink type. Only undefined is valid.");
  }

  // We account for the memory usage of the WritableStreamDefaultController and AbortSignal together
  // because their lifetimes are identical and memory accounting itself has a memory overhead.
  auto controller = js.allocAccounted<WritableStreamDefaultController>(
      sizeof(WritableStreamDefaultController) + sizeof(AbortSignal), js, owner,
      js.alloc<AbortSignal>());
  auto& controllerRef = *controller;
  state.transitionTo<Controller>(kj::mv(controller));
  controllerRef.setup(js, kj::mv(underlyingSink), kj::mv(queuingStrategy));
}

kj::Maybe<jsg::Promise<void>> WritableStreamJsController::tryPipeFrom(
    jsg::Lock& js, jsg::Ref<ReadableStream> source, PipeToOptions options) {
  JSG_REQUIRE_NONNULL(
      ioContext, Error, "Unable to pipe to a WritableStream created outside of a request");

  // The ReadableStream source here can be either a JavaScript-backed ReadableStream
  // or ReadableStreamSource-backed. In either case, however, this WritableStream is
  // JavaScript-based and must use a JavaScript promise-based data flow for piping data.
  // We'll treat all ReadableStreams as if they are JavaScript-backed.
  //
  // This method will return a JavaScript promise that is resolved when the pipe operation
  // completes, or is rejected if the pipe operation is aborted or errored.

  // Let's also acquire the destination pipe lock.
  lock.pipeLock(owner.assertLive(), kj::mv(source), options);

  return pipeLoop(js).then(js, [ref = addRef()](auto& js) {});
}

jsg::Promise<void> WritableStreamJsController::pipeLoop(jsg::Lock& js) {
  auto maybePipeLock = lock.tryGetPipe();
  if (maybePipeLock == kj::none) return js.resolvedPromise();
  auto& pipeLock = KJ_REQUIRE_NONNULL(maybePipeLock);

  auto preventAbort = pipeLock.flags.preventAbort;
  auto preventCancel = pipeLock.flags.preventCancel;
  auto preventClose = pipeLock.flags.preventClose;
  auto pipeThrough = pipeLock.flags.pipeThrough;
  // At the start of each pipe step, we check to see if either the source or
  // the destination has closed or errored and propagate that on to the other.
  //
  // In the terminal branches below, the source's pipe lock is always released via
  // pipeLock.releaseSource() *before* lock.releasePipeLock() destroys the write-side
  // pipe lock state (which holds our kj::Ptr to the source's PipeController and the
  // jsg::Ref keeping the source alive).
  KJ_IF_SOME(promise, pipeLock.checkSignal(js, *this)) {
    // checkSignal released the source's pipe lock itself.
    lock.releasePipeLock();
    return kj::mv(promise);
  }

  KJ_IF_SOME(errored, pipeLock.source->tryGetErrored(js)) {
    pipeLock.releaseSource(js);
    lock.releasePipeLock();
    if (!preventAbort) {
      auto onSuccess = [pipeThrough, reason = errored.addRef(js)](jsg::Lock& js) {
        return rejectedMaybeHandledPromise<void>(js, reason.getHandle(js), pipeThrough);
      };
      auto promise = abort(js, errored);
      KJ_IF_SOME(ioContext, IoContext::tryCurrent()) {
        return promise.then(js, ioContext.addFunctor(kj::mv(onSuccess)));
      } else {
        return promise.then(js, kj::mv(onSuccess));
      }
    }
    return rejectedMaybeHandledPromise<void>(js, errored, pipeThrough);
  }

  KJ_IF_SOME(errored, state.tryGetUnsafe<StreamStates::Errored>()) {
    auto reason = errored.getHandle(js);
    if (!preventCancel) {
      pipeLock.releaseSource(js, reason);
    } else {
      pipeLock.releaseSource(js);
    }
    lock.releasePipeLock();
    return rejectedMaybeHandledPromise<void>(js, reason, pipeThrough);
  }

  KJ_IF_SOME(erroring, isErroring(js)) {
    if (!preventCancel) {
      pipeLock.releaseSource(js, erroring);
    } else {
      pipeLock.releaseSource(js);
    }
    lock.releasePipeLock();
    return rejectedMaybeHandledPromise<void>(js, erroring, pipeThrough);
  }

  if (pipeLock.source->isClosed()) {
    pipeLock.releaseSource(js);
    lock.releasePipeLock();
    if (!preventClose) {
      auto promise = close(js);
      if (pipeThrough) {
        promise.markAsHandled(js);
      }
      return kj::mv(promise);
    }
    return js.resolvedPromise();
  }

  if (state.is<StreamStates::Closed>()) {
    auto reason = js.typeError("This destination writable stream is closed."_kj);
    if (!preventCancel) {
      pipeLock.releaseSource(js, reason);
    } else {
      pipeLock.releaseSource(js);
    }
    lock.releasePipeLock();

    return rejectedMaybeHandledPromise<void>(js, reason, pipeThrough);
  }

  // Assuming we get by that, we perform a read on the source. If the read errors,
  // we propagate the error to the destination, depending on options and reject
  // the pipe promise. If the read is successful then we'll get a ReadResult
  // back. If the ReadResult indicates done, then we close the destination
  // depending on options and resolve the pipe promise. If the ReadResult is
  // not done, we write the value on to the destination. If the write operation
  // fails, we reject the pipe promise and propagate the error back to the
  // source (again, depending on options). If the write operation is successful,
  // we call pipeLoop again to move on to the next iteration.

  auto onSuccess = [this, ref = addRef(), preventCancel, pipeThrough](
                       jsg::Lock& js, ReadResult result) mutable -> jsg::Promise<void> {
    auto maybePipeLock = lock.tryGetPipe();
    if (maybePipeLock == kj::none) return js.resolvedPromise();
    auto& pipeLock = KJ_REQUIRE_NONNULL(maybePipeLock);

    KJ_IF_SOME(promise, pipeLock.checkSignal(js, *this)) {
      lock.releasePipeLock();
      return kj::mv(promise);
    }  // Trailing else() is squash compiler warning

    if (result.done) {
      // We'll handle the close at the start of the next iteration.
      return pipeLoop(js);
    }

    auto onSuccess = [this, ref = addRef()](jsg::Lock& js) { return pipeLoop(js); };

    auto onFailure = [this, ref = addRef(), preventCancel, pipeThrough](
                         jsg::Lock& js, jsg::V8Ref<v8::Value> exception) mutable {
      // The write failed. We need to release the source if the pipe lock still exists.
      // The write-side pipe lock is left in place; doError() cleans it up when the
      // underlying error propagates to this controller.
      auto reason = jsg::JsValue(exception.getHandle(js));
      KJ_IF_SOME(pipeLock, lock.tryGetPipe()) {
        if (!preventCancel) {
          pipeLock.releaseSource(js, reason);
        } else {
          pipeLock.releaseSource(js);
        }
      }  // Trailing else() to squash compiler warning
      return rejectedMaybeHandledPromise<void>(js, reason, pipeThrough);
    };

    auto promise = write(
        js, result.value.map([&](jsg::JsRef<jsg::JsValue>& value) { return value.getHandle(js); }));

    return maybeAddFunctor(js, kj::mv(promise), kj::mv(onSuccess), kj::mv(onFailure));
  };

  auto onFailure = [this, ref = addRef()](jsg::Lock& js, jsg::Value value) mutable {
    // The read failed. We will handle the error at the start of the next iteration.
    return pipeLoop(js);
  };

  return maybeAddFunctor(js, pipeLock.source->read(js), kj::mv(onSuccess), kj::mv(onFailure));
}

void WritableStreamJsController::updateBackpressure(jsg::Lock& js, bool backpressure) {
  KJ_IF_SOME(writerLock, lock.state.tryGetUnsafe<WriterLocked>()) {
    if (backpressure) {
      // Per the spec, when backpressure is updated and is true, we replace the existing
      // ready promise on the writer with a new pending promise, regardless of whether
      // the existing one is resolved or not.
      auto prp = js.newPromiseAndResolver<void>();
      prp.promise.markAsHandled(js);
      return writerLock.setReadyFulfiller(js, prp);
    }

    // When backpressure is updated and is false, we resolve the ready promise on the writer
    maybeResolvePromise(js, writerLock.getReadyFulfiller());
  }
}

jsg::Promise<void> WritableStreamJsController::write(
    jsg::Lock& js, jsg::Optional<jsg::JsValue> value) {
  KJ_SWITCH_ONEOF(state) {
    KJ_CASE_ONEOF(initial, Initial) {
      return js.rejectedPromise<void>(js.typeError("This WritableStream has been closed."_kj));
    }
    KJ_CASE_ONEOF(closed, StreamStates::Closed) {
      return js.rejectedPromise<void>(js.typeError("This WritableStream has been closed."_kj));
    }
    KJ_CASE_ONEOF(errored, StreamStates::Errored) {
      return js.rejectedPromise<void>(errored.getHandle(js));
    }
    KJ_CASE_ONEOF(controller, Controller) {
      return controller->write(js, value.orDefault(js.undefined()));
    }
  }
  KJ_UNREACHABLE;
}

void WritableStreamJsController::visitForGc(jsg::GcVisitor& visitor) {
  state.visitForGc(visitor);
  visitor.visit(maybeAbortPromise, lock);
}

